" class="deadline-secondary small edit-progres-btn" data-update-url="{{ route('laporan.update-progres', $latestProgresCheckpoint) }}" data-tujuan-satuan-id="{{ $latestProgresCheckpoint->tujuan_satuan_id }}" data-perihal="{{ e($latestProgresCheckpoint->perihal) }}" data-proyek="{{ e($latestProgresCheckpoint->proyek ?? '') }}" data-prioritas="{{ e($latestProgresCheckpoint->prioritas) }}" data-deskripsi="{{ e($latestProgresCheckpoint->deskripsi) }}" data-kendala="{{ e($latestProgresCheckpoint->kendala ?? '') }}" data-progres="{{ $latestProgresCheckpoint->progres }}">Edit</button>@endif @endif</div>@else<span class="deadline-complete">✓ Laporan sudah dikirim</span>@endif</div></article>@empty<div class="empty-state"><svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="var(--text-dim)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="4" width="12" height="17" rx="2"></rect><path d="M9 4h6"></path><path d="M9 10h6"></path><path d="M9 14h6"></path><path d="M9 18h3"></path></svg><div class="empty-state-title">Belum ada permintaan laporan</div><div class="empty-state-sub">Tugas pelaporan dari Danpus/Wadan akan muncul di sini.</div></div>@endforelse</div></div></section>@endif
<section id="masuk" class="tab-panel"><div class="panel"><div class="panel-head"><div><h2>Laporan Masuk</h2><p>Laporan yang dikirim oleh satuan lain kepada {{ $satuan->nama }}. Buka detail untuk membaca isi dan menindaklanjuti laporan.</p></div></div><div class="tbl-wrap"><table class="dtbl"><thead><tr><th style="text-align:center">Pengirim</th><th>Perihal</th><th>Prioritas</th><th style="text-align:center">Tanggal</th><th style="text-align:center">Status</th>@if($canReview)<th style="text-align:center">Aksi</th>@endif</tr></thead><tbody>@forelse($laporanMasuk as $l)<tr data-search="{{ strtolower(($l->satuan->nama ?? '').' '.$l->perihal) }}" data-prioritas="{{ $l->prioritas }}"><td style="text-align:center">{{ $l->satuan->nama ?? '-' }}</td><td>{{ $l->perihal }}</td><td>{{ $l->prioritas }}</td><td style="text-align:center">{{ $l->created_at->translatedFormat('d M Y H:i') }}</td><td style="text-align:center"><span class="status-dot {{ str_contains(strtolower($l->status),'setuj') || str_contains(strtolower($l->status),'diterima') ? 'green' : (str_contains(strtolower($l->status),'tolak') ? 'bad' : 'amber') }}">{{ $l->status }}</span></td>@if($canReview)<td><div class="review-actions" style="justify-content:center"><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($l->satuan->nama ?? '-') }}" data-tujuan="{{ e($satuan->nama) }}" data-perihal="{{ e($l->perihal) }}" data-prioritas="{{ e($l->prioritas) }}" data-progres="{{ $l->progres }}" data-kendala="{{ e($l->kendala ?? '') }}" data-proyek="{{ e($l->proyek ?? '-') }}" data-tanggal="{{ e($l->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($l->deskripsi) }}" data-lampiran="{{ $l->lampiran_path ? e(asset('storage/'.$l->lampiran_path)) : '' }}">Lihat</button><form method="POST" action="{{ route('laporan.status', $l) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Diterima"><button class="approve" type="submit">Terima</button></form><form method="POST" action="{{ route('laporan.status', $l) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Revisi"><button type="submit">Revisi</button></form><form method="POST" action="{{ route('laporan.status', $l) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="Ditolak"><button class="reject" type="submit">Tolak</button></form></div></td>@endif</tr>@empty<tr><td colspan="6"><div class="empty-state"><svg viewBox="0 0 24 24" width="34" height="34" fill="none" stroke="var(--text-dim)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="4" width="12" height="17" rx="2"></rect><path d="M9 4h6"></path><path d="M9 10h6"></path><path d="M9 14h6"></path><path d="M9 18h3"></path></svg><div class="empty-state-title">Belum ada laporan masuk</div><div class="empty-state-sub">Laporan dari satuan lain akan muncul di sini.</div></div></td></tr>@endforelse</tbody></table></div></div></section>
