<script>
(function(){const btn=document.getElementById('profileMenuBtn'),drop=document.getElementById('profileDropdown');if(btn&&drop&&!btn.dataset.uiBound){btn.dataset.uiBound='1';btn.addEventListener('click',e=>{e.stopPropagation();drop.classList.toggle('open')});}document.addEventListener('click',e=>{if(drop&&!drop.parentElement.contains(e.target))drop.classList.remove('open')});window.openProfileModal=function(id){document.querySelectorAll('#profileModalOverlay .profile-dropdown-view').forEach(v=>v.style.display=v.id===id?'block':'none');document.getElementById('profileModalOverlay').classList.add('open')};document.getElementById('profileModalCloseBtn')?.addEventListener('click',()=>document.getElementById('profileModalOverlay').classList.remove('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('profileModalOverlay')?.classList.contains('open'))document.getElementById('profileModalOverlay').classList.remove('open')});document.getElementById('sidebar');(function(){const themeBtn=document.getElementById('themeToggleBtn');if(!themeBtn||themeBtn.dataset.uiBound)return;themeBtn.dataset.uiBound='1';const THEME_KEY='siberad-theme';function applyTheme(theme){if(theme==='light')document.documentElement.setAttribute('data-theme','light');else document.documentElement.removeAttribute('data-theme');themeBtn.setAttribute('aria-pressed',theme==='light'?'true':'false');}let savedTheme='dark';try{savedTheme=localStorage.getItem(THEME_KEY)||'dark';}catch(e){}applyTheme(savedTheme);themeBtn.addEventListener('click',()=>{const current=document.documentElement.getAttribute('data-theme')==='light'?'light':'dark';const next=current==='light'?'dark':'light';try{localStorage.setItem(THEME_KEY,next);}catch(e){}applyTheme(next);});})();const sidebar=document.getElementById('sidebar');const ROLE_GROUP_STATE_KEY='siberad-role-group-';function positionGroupFlyout(g){const subnav=g.querySelector('.side-subnav');const gbtn=g.querySelector('.side-nav-group-title');if(!subnav||!gbtn)return;if(!sidebar?.classList.contains('collapsed')||!g.classList.contains('open')){subnav.style.top='';subnav.style.left='';return;}const r=gbtn.getBoundingClientRect();subnav.style.top=r.top+'px';subnav.style.left=(r.right+8)+'px';}window.siberadRepositionSubnavFlyouts=function(){document.querySelectorAll('.side-nav-group').forEach(positionGroupFlyout);};window.addEventListener('resize',()=>window.siberadRepositionSubnavFlyouts());function restoreRoleGroupState(){document.querySelectorAll('.side-nav-group').forEach(g=>{let saved=null;try{saved=sessionStorage.getItem(ROLE_GROUP_STATE_KEY+g.id)}catch(e){}if(saved==='closed'||sidebar?.classList.contains('collapsed'))g.classList.remove('open');else if(saved==='open')g.classList.add('open');positionGroupFlyout(g);});}window.siberadRestoreGroupState=restoreRoleGroupState;restoreRoleGroupState();document.querySelectorAll('.side-nav-group').forEach(g=>{const gbtn=g.querySelector('.side-nav-group-title');gbtn?.addEventListener('click',e=>{e.stopPropagation();const willOpen=!g.classList.contains('open');if(willOpen&&sidebar?.classList.contains('collapsed')){document.querySelectorAll('.side-nav-group.open').forEach(other=>{if(other===g)return;other.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+other.id,'closed')}catch(err){}positionGroupFlyout(other);});}g.classList.toggle('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,g.classList.contains('open')?'open':'closed')}catch(e){}positionGroupFlyout(g);});});document.addEventListener('click',e=>{if(!sidebar?.classList.contains('collapsed'))return;if(e.target.closest('#sideCollapseBtn'))return;document.querySelectorAll('.side-nav-group.open').forEach(g=>{if(g.contains(e.target))return;g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);});});document.addEventListener('keydown',e=>{if(e.key!=='Escape'||!sidebar?.classList.contains('collapsed'))return;document.querySelectorAll('.side-nav-group.open').forEach(g=>{g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);});});document.querySelectorAll('.side-nav-group .side-sub-link').forEach(a=>a.addEventListener('click',()=>{if(!sidebar?.classList.contains('collapsed'))return;const g=a.closest('.side-nav-group');if(!g)return;g.classList.remove('open');try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+g.id,'closed')}catch(err){}positionGroupFlyout(g);}));const ROLE_ACTIVE_TAB_KEY='siberad-role-active-tab';function showRoleSection(id,link,skipSave){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.remove('active'));const el=document.getElementById(id);if(!el)return;el.classList.add('active');document.querySelectorAll('.side-link,.side-sub-link').forEach(x=>x.classList.remove('active'));if(link)link.classList.add('active');document.querySelectorAll('.side-nav-group').forEach(g=>g.classList.remove('has-active-child'));const activeGroup=link?.closest('.side-nav-group');if(activeGroup){activeGroup.classList.add('has-active-child');if(activeGroup.id)try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+activeGroup.id,'open')}catch(e){}}document.getElementById('sidebar')?.classList.remove('open');if(!skipSave){try{sessionStorage.setItem(ROLE_ACTIVE_TAB_KEY,id)}catch(e){}}}document.querySelectorAll('.side-link[href^="#"],.side-sub-link[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);if(!document.getElementById(id))return;e.preventDefault();showRoleSection(id,a)}));(function(){let savedId=null;try{savedId=sessionStorage.getItem(ROLE_ACTIVE_TAB_KEY)}catch(e){}if(!savedId)return;function attempt(tries){if(!document.getElementById(savedId)){if(tries<20)setTimeout(()=>attempt(tries+1),50);return;}const link=document.querySelector('.side-link[href="#'+savedId+'"],.side-sub-link[href="#'+savedId+'"]');showRoleSection(savedId,link,true);const group=link?.closest('.side-nav-group');if(group){group.classList.add('open');if(group.id)try{sessionStorage.setItem(ROLE_GROUP_STATE_KEY+group.id,'open')}catch(e){}positionGroupFlyout(group);}}attempt(0);})();window.siberadCharts=window.siberadCharts||[];const ctx=document.getElementById('laporanChart');if(ctx)window.siberadCharts.push(new Chart(ctx,{type:'doughnut',data:{labels:['Disetujui','Ditolak','Terlambat','Dibatalkan'],datasets:[{data:[{{ $stats['disetujui'] }},{{ $stats['ditolak'] }},{{ $stats['terlambat'] }},{{ $stats['dibatalkan'] }}],backgroundColor:['#22c55e','#ef4444','#ff6b6b','#c1121f'],borderColor:'transparent',borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}}));})();
window.openReportDetail=function(button){const modal=document.getElementById('reportDetailModal');document.getElementById('detailPengirim').textContent=button.dataset.pengirim||'-';document.getElementById('detailTujuan').textContent=button.dataset.tujuan||'-';document.getElementById('detailPerihal').textContent=button.dataset.perihal||'-';document.getElementById('detailPrioritas').textContent=button.dataset.prioritas||'-';document.getElementById('detailProgres').textContent=button.dataset.progres?button.dataset.progres+'%':'-';document.getElementById('detailProyek').textContent=button.dataset.proyek||'-';document.getElementById('detailTanggal').textContent=button.dataset.tanggal||'-';document.getElementById('detailDeskripsi').textContent=button.dataset.deskripsi||'-';const kendala=button.dataset.kendala||'';const kendalaWrap=document.getElementById('detailKendalaWrap');if(kendala){document.getElementById('detailKendala').textContent=kendala;kendalaWrap.style.display='block'}else{kendalaWrap.style.display='none'}const lampiran=button.dataset.lampiran||'';const wrap=document.getElementById('detailLampiranWrap');const link=document.getElementById('detailLampiran');if(lampiran){link.href=lampiran;wrap.style.display='block'}else{wrap.style.display='none'}document.getElementById('detailActions').innerHTML=button.dataset.readonly==='1'?'<span style="font-size:11px;color:var(--text-muted);margin-right:auto">'+(button.dataset.readonlyText||'Detail ini hanya untuk melihat, tidak ada tindakan lebih lanjut.')+'</span>':'<span style="font-size:11px;color:var(--text-muted);margin-right:auto">Gunakan tombol aksi pada tabel untuk menindaklanjuti laporan.</span>';modal.classList.add('open')};document.getElementById('reportDetailClose')?.addEventListener('click',()=>document.getElementById('reportDetailModal').classList.remove('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('reportDetailModal')?.classList.contains('open'))document.getElementById('reportDetailModal').classList.remove('open')});
document.getElementById('kirimLaporanOpen')?.addEventListener('click',()=>document.getElementById('kirimLaporanModal')?.classList.add('open'));document.getElementById('kirimLaporanClose')?.addEventListener('click',()=>document.getElementById('kirimLaporanModal')?.classList.remove('open'));document.getElementById('kirimLaporanCancel')?.addEventListener('click',()=>document.getElementById('kirimLaporanModal')?.classList.remove('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('kirimLaporanModal')?.classList.contains('open'))document.getElementById('kirimLaporanModal').classList.remove('open')});
(function(){
  const form=document.getElementById('kirimLaporanForm');
  const konfirmOverlay=document.getElementById('konfirmasiKirimOverlay');
  if(!form||!konfirmOverlay)return;
  function closeKonfirm(){konfirmOverlay.classList.remove('open')}
  form.addEventListener('submit',function(e){
    if(form.dataset.confirmed==='1'){form.dataset.confirmed='';return}
    e.preventDefault();
    konfirmOverlay.classList.add('open');
  });
  document.getElementById('konfirmasiKirimYa')?.addEventListener('click',function(){
    closeKonfirm();
    form.dataset.confirmed='1';
    form.requestSubmit?form.requestSubmit():form.submit();
  });
  document.getElementById('konfirmasiKirimBatal')?.addEventListener('click',closeKonfirm);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&konfirmOverlay.classList.contains('open'))closeKonfirm()});
})();
</script>
</body></html>